export default function prepare({ payload, dataSourceId, personId }) {
  if (
    typeof dataSourceId !== "string" ||
    !dataSourceId.trim() ||
    dataSourceId.startsWith("YOUR_") ||
    typeof personId !== "string" ||
    !personId.trim() ||
    personId.startsWith("YOUR_")
  )
    throw Error("Configure the Notion data source and person");
  if (
    !payload ||
    typeof payload.email !== "string" ||
    !payload.email.trim() ||
    typeof payload.name !== "string" ||
    !payload.name.trim()
  )
    throw Error("Booking is missing the invitee name or email");
  const e = payload.scheduled_event,
    start = e?.start_time,
    end = e?.end_time;
  if (
    typeof start !== "string" ||
    typeof end !== "string" ||
    !Number.isFinite(Date.parse(start)) ||
    !Number.isFinite(Date.parse(end)) ||
    Date.parse(end) <= Date.parse(start)
  )
    throw Error("Booking has invalid scheduled event times");
  const contact = { email: payload.email, full_name: payload.name };
  for (const k of ["first_name", "last_name"])
    if (typeof payload[k] === "string" && payload[k].trim()) contact[k] = payload[k];
  return { data: [contact], booking: { start, end }, dataSourceId, personId };
}

