export default function dropcontactSubmission({ error, success, requestId, raw, count }) {
  if (
    error !== false ||
    success !== true ||
    typeof requestId !== "string" ||
    !requestId.trim() ||
    !raw ||
    typeof raw !== "object" ||
    Array.isArray(raw)
  )
    throw new Error(
      "Dropcontact did not confirm the enrichment request; submission may already have occurred",
    );
  if (!Number.isInteger(count) || count < 1 || count > 250)
    throw new Error("Invalid enrichment contact count");
  return { requestId, count, submission: raw };
}

