export default function page({ data, error, success, status, booking, dataSourceId, personId }) {
  if (
    error !== false ||
    success !== true ||
    status !== "succeeded" ||
    !Array.isArray(data) ||
    data.length !== 1
  )
    throw Error("Dropcontact enrichment is not complete; inspect the request before retrying");
  if (
    typeof dataSourceId !== "string" ||
    !dataSourceId.trim() ||
    dataSourceId.startsWith("YOUR_") ||
    typeof personId !== "string" ||
    !personId.trim() ||
    personId.startsWith("YOUR_")
  )
    throw Error("Configure the Notion data source and person");
  const r = data[0],
    email = r?.email?.[0]?.email;
  if (
    typeof r?.full_name !== "string" ||
    !r.full_name.trim() ||
    typeof email !== "string" ||
    !email.trim()
  )
    throw Error("Enriched contact is missing full name or first email");
  const properties = {
    Date: { date: { start: booking.start, end: booking.end } },
    email: { email },
    Leads: { title: [{ text: { content: r.full_name } }] },
    Person: { people: [{ id: personId }] },
  };
  for (const [source, target] of [
    ["linkedin", "LinkedIn Profile"],
    ["website", "Website"],
    ["company_linkedin", "LinkedIn Company"],
  ]) {
    const v = r[source];
    if (v === undefined || v === null || v === "") continue;
    if (typeof v !== "string") throw Error("Invalid enriched URL");
    properties[target] = { url: v };
  }
  if (r.civility !== undefined && r.civility !== null && r.civility !== "") {
    if (typeof r.civility !== "string") throw Error("Invalid civility");
    properties.Civility = { rich_text: [{ text: { content: r.civility } }] };
  }
  return { parent: { data_source_id: dataSourceId }, properties };
}

