export default function notionBookingCreated({ page }) {
  if (
    !page ||
    typeof page !== "object" ||
    Array.isArray(page) ||
    page.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id.trim()
  ) {
    throw new Error("Notion did not return a created page ID");
  }
  return { page };
}
